<script setup lang="ts">
import {useHysRootAttrs} from '../../config'
const hysRootAttrs=useHysRootAttrs()
import {ref,onBeforeUnmount,onDeactivated} from 'vue';import {Search,X,LoaderCircle} from 'lucide-vue-next'
const props=withDefaults(defineProps<{modelValue:string;placeholder?:string;delay?:number;disabled?:boolean;readonly?:boolean;clearable?:boolean;loading?:boolean;ariaLabel?:string}>(),{delay:300,placeholder:'搜索…',clearable:true}),emit=defineEmits<{'update:modelValue':[value:string];search:[value:string];clear:[];focus:[event:FocusEvent];blur:[event:FocusEvent]}>(),input=ref<HTMLInputElement>()
let timer:ReturnType<typeof setTimeout>|undefined;function search(value:string){clearTimeout(timer);if(!props.disabled)emit('search',value)}function change(value:string){if(props.disabled||props.readonly)return;emit('update:modelValue',value);clearTimeout(timer);timer=setTimeout(()=>search(value),props.delay)}onBeforeUnmount(()=>clearTimeout(timer));onDeactivated(()=>clearTimeout(timer));defineExpose({focus:()=>input.value?.focus(),blur:()=>input.value?.blur()})
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-ex-search"><LoaderCircle v-if="loading" class="hys-ui-icon-spin" :size="16"/><Search v-else :size="16" aria-hidden="true"/><input ref="input" type="search" :value="modelValue" :placeholder="placeholder" :disabled="disabled" :readonly="readonly" :aria-label="ariaLabel||'搜索'" @input="change(($event.target as HTMLInputElement).value)" @keydown.enter="!$event.isComposing&&search(modelValue)" @focus="emit('focus',$event)" @blur="emit('blur',$event)"/><button v-if="clearable&&modelValue&&!disabled&&!readonly" type="button" aria-label="清空搜索" @click="change('');emit('clear');input?.focus()"><X :size="14"/></button></div></template>
